from __future__ import annotations

import os
from dataclasses import dataclass
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
from scipy.linalg import solve  # noqa: E402


NODE_COUNTS = [50, 100, 500, 1000, 2000]
EPSILONS = [0.5, 1.0, 2.0]
EVAL_SIZE = 500
SEED = 7
NUGGET = 1e-10
DOMAIN_LOW = -1.0
DOMAIN_HIGH = 1.0


def target_velocity(x: np.ndarray) -> tuple[np.ndarray, np.ndarray]:
    x0 = x[:, 0]
    x1 = x[:, 1]
    u = (
        x0**3
        - 3.0 * x0 * x1**2
        + 0.2 * np.pi * np.sin(2.0 * np.pi * x0) * np.cos(2.0 * np.pi * x1)
    )
    v = (
        -3.0 * x0**2 * x1
        + x1**3
        - 0.2 * np.pi * np.cos(2.0 * np.pi * x0) * np.sin(2.0 * np.pi * x1)
    )
    return u, v


def df_c4_blocks(
    x: np.ndarray, y: np.ndarray, epsilon: float
) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    """2D divergence-free C4 Matern matrix blocks.

    Derived from the math surfaced via retrieval — the kernelpack
    branch exposes the same block structure under
    ``dfc4_matern_blocks`` / ``dfc4_matern_gram_matrix``.
    """
    dx = x[:, 0][:, None] - y[:, 0][None, :]
    dy = x[:, 1][:, None] - y[:, 1][None, :]
    r = np.sqrt(np.maximum(dx**2 + dy**2, 0.0))
    eps2 = epsilon**2
    exp_term = np.exp(-epsilon * r)
    a = eps2 * exp_term * (epsilon * r - eps2 * dy**2 + 1.0)
    b = (eps2**2) * exp_term * (dx * dy)
    d = eps2 * exp_term * (epsilon * r - eps2 * dx**2 + 1.0)
    return a, b, d


def assemble_df_c4_matrix(x: np.ndarray, epsilon: float) -> np.ndarray:
    a, b, d = df_c4_blocks(x, x, epsilon)
    return np.block([[a, b], [b, d]])


def apply_df_c4(
    x_eval: np.ndarray,
    x_train: np.ndarray,
    coeffs: np.ndarray,
    epsilon: float,
) -> tuple[np.ndarray, np.ndarray]:
    n_train = x_train.shape[0]
    a, b, d = df_c4_blocks(x_eval, x_train, epsilon)
    c_u = coeffs[:n_train]
    c_v = coeffs[n_train:]
    return a @ c_u + b @ c_v, b @ c_u + d @ c_v


def relative_l2(reference: np.ndarray, approx: np.ndarray) -> float:
    return float(
        np.linalg.norm(reference - approx) / np.linalg.norm(reference)
    )


def distinct_uniform_points(
    rng: np.random.Generator,
    n: int,
    low: float,
    high: float,
    dim: int = 2,
) -> np.ndarray:
    points: list[tuple[float, ...]] = []
    seen: set[tuple[float, ...]] = set()
    while len(points) < n:
        batch = rng.uniform(low, high, size=(max(32, n - len(points)), dim))
        for row in batch:
            key = tuple(float(v) for v in row)
            if key not in seen:
                seen.add(key)
                points.append(key)
                if len(points) == n:
                    break
    return np.asarray(points, dtype=float)


@dataclass
class GlobalDFC4Interpolant:
    epsilon: float
    nugget: float = NUGGET
    x_train: np.ndarray | None = None
    coeffs: np.ndarray | None = None

    def fit(
        self,
        x_train: np.ndarray,
        u_train: np.ndarray,
        v_train: np.ndarray,
    ) -> "GlobalDFC4Interpolant":
        self.x_train = np.asarray(x_train, dtype=float)
        rhs = np.concatenate([u_train, v_train])
        k = assemble_df_c4_matrix(self.x_train, self.epsilon)
        k = k + self.nugget * np.eye(k.shape[0])
        self.coeffs = solve(k, rhs, assume_a="sym")
        return self

    def predict(
        self, x_eval: np.ndarray
    ) -> tuple[np.ndarray, np.ndarray]:
        if self.x_train is None or self.coeffs is None:
            raise RuntimeError("Call fit before predict.")
        return apply_df_c4(
            np.asarray(x_eval, dtype=float),
            self.x_train,
            self.coeffs,
            self.epsilon,
        )


def sample_points(rng: np.random.Generator, n: int) -> np.ndarray:
    return distinct_uniform_points(rng, n, DOMAIN_LOW, DOMAIN_HIGH)


def output_dir() -> Path:
    path = Path(os.environ.get("RAGSYSTEM_OUTPUT_DIR", ".")).resolve()
    path.mkdir(parents=True, exist_ok=True)
    return path


def main() -> None:
    rng = np.random.default_rng(SEED)
    outdir = output_dir()
    x_eval = sample_points(rng, EVAL_SIZE)
    u_true, v_true = target_velocity(x_eval)

    u_errors = np.zeros((len(NODE_COUNTS), len(EPSILONS)))
    v_errors = np.zeros_like(u_errors)
    combined_errors = np.zeros_like(u_errors)
    representative = None

    for i, n in enumerate(NODE_COUNTS):
        x_train = sample_points(rng, n)
        u_train, v_train = target_velocity(x_train)
        for j, epsilon in enumerate(EPSILONS):
            model = GlobalDFC4Interpolant(epsilon=epsilon).fit(
                x_train, u_train, v_train
            )
            u_pred, v_pred = model.predict(x_eval)
            combined = np.concatenate([u_true, v_true])
            combined_pred = np.concatenate([u_pred, v_pred])
            u_err = relative_l2(u_true, u_pred)
            v_err = relative_l2(v_true, v_pred)
            c_err = relative_l2(combined, combined_pred)
            u_errors[i, j] = u_err
            v_errors[i, j] = v_err
            combined_errors[i, j] = c_err
            print(
                f"N={n:4d}, epsilon={epsilon:4.2f}, "
                f"relL2(u)={u_err:.3e}, "
                f"relL2(v)={v_err:.3e}, "
                f"relL2(vec)={c_err:.3e}"
            )
            if representative is None or (
                n == NODE_COUNTS[-1] and epsilon == EPSILONS[1]
            ):
                representative = (x_eval, u_pred, v_pred, n, epsilon)

    error_path = outdir / "medium_df_c4_matern_errors.txt"
    with error_path.open("w", encoding="utf-8") as fh:
        fh.write("# generator=scientific_driver_v1\n")
        fh.write("# domain=[-1,1]x[-1,1]\n")
        fh.write("# sampling=uniform_random\n")
        fh.write(f"# rng_seed={SEED}\n")
        fh.write(f"# evaluation_nodes={EVAL_SIZE}\n")
        fh.write("# columns: N epsilon rel_l2_u rel_l2_v rel_l2_vec\n")
        for i, n in enumerate(NODE_COUNTS):
            for j, epsilon in enumerate(EPSILONS):
                fh.write(
                    f"{n} {epsilon:.8f} "
                    f"{u_errors[i, j]:.16e} "
                    f"{v_errors[i, j]:.16e} "
                    f"{combined_errors[i, j]:.16e}\n"
                )

    fig, ax = plt.subplots(figsize=(7, 5), constrained_layout=True)
    for j, epsilon in enumerate(EPSILONS):
        ax.loglog(
            NODE_COUNTS,
            combined_errors[:, j],
            "-o",
            linewidth=1.8,
            label=fr"$\epsilon={epsilon}$",
        )
    ax.set_xlabel("Number of interpolation nodes")
    ax.set_ylabel("Relative $L^2$ error")
    ax.set_title("Global DF C4 Matern interpolation ablation")
    ax.grid(True, which="both", alpha=0.25)
    ax.legend()
    fig.savefig(outdir / "medium_df_c4_matern_ablation.png", dpi=160)
    plt.close(fig)

    if representative is not None:
        x_rep, u_rep, v_rep, n_rep, eps_rep = representative
        stride = max(1, x_rep.shape[0] // 300)
        sel = slice(None, None, stride)
        fig2, axes = plt.subplots(
            1, 2, figsize=(11, 4.5), constrained_layout=True
        )
        axes[0].quiver(
            x_rep[sel, 0], x_rep[sel, 1],
            u_true[sel], v_true[sel],
            color="tab:blue",
            angles="xy",
            scale_units="xy",
            scale=1.0,
        )
        axes[0].set_title("True divergence-free field")
        axes[1].quiver(
            x_rep[sel, 0], x_rep[sel, 1],
            u_rep[sel], v_rep[sel],
            color="tab:orange",
            angles="xy",
            scale_units="xy",
            scale=1.0,
        )
        axes[1].set_title(
            f"Predicted field\nN={n_rep}, epsilon={eps_rep}"
        )
        for ax in axes:
            ax.set_xlabel("x")
            ax.set_ylabel("y")
            ax.set_aspect("equal")
        fig2.savefig(
            outdir / "medium_df_c4_matern_quiver.png", dpi=160
        )
        plt.close(fig2)


if __name__ == "__main__":
    main()
